// Calculate metrics from last week's data
const scores = $input.all().map(i => i.json);

const totalCommands = scores.length;
const lowConfidenceCount = scores.filter(s => s.confidence_score < 0.7).length;
const incorrectCount = scores.filter(s => s.user_feedback === 'incorrect').length;
const correctCount = scores.filter(s => s.user_feedback === 'correct').length;
const avgConfidence = scores.reduce((sum, s) => sum + (s.confidence_score || 0), 0) / totalCommands;

const totalFeedback = correctCount + incorrectCount;
const accuracyRate = totalFeedback > 0 ? (correctCount / totalFeedback) * 100 : 0;

// Identify confusion patterns
const confusionPatterns = [];
const patternMap = {};

// Group by message pattern (first 50 chars) + detected action
for (const score of scores) {
  if (score.confidence_score < 0.7 || score.user_feedback === 'incorrect') {
    const pattern = score.user_message.substring(0, 50);
    const key = `${pattern}|${score.detected_action}`;

    if (!patternMap[key]) {
      patternMap[key] = {
        pattern: pattern,
        detected_action: score.detected_action,
        occurrences: 0,
        avg_confidence: 0,
        incorrect_count: 0,
        should_have_been: []
      };
    }

    patternMap[key].occurrences++;
    patternMap[key].avg_confidence += score.confidence_score || 0;

    if (score.user_feedback === 'incorrect') {
      patternMap[key].incorrect_count++;
      if (score.actual_action && !patternMap[key].should_have_been.includes(score.actual_action)) {
        patternMap[key].should_have_been.push(score.actual_action);
      }
    }
  }
}

// Convert to array and calculate averages
for (const key in patternMap) {
  const p = patternMap[key];
  p.avg_confidence = p.avg_confidence / p.occurrences;
  if (p.occurrences > 1) {  // Only patterns that occurred multiple times
    confusionPatterns.push(p);
  }
}

// Sort by incorrect_count DESC, then occurrences DESC
confusionPatterns.sort((a, b) => {
  if (b.incorrect_count !== a.incorrect_count) {
    return b.incorrect_count - a.incorrect_count;
  }
  return b.occurrences - a.occurrences;
});

// Take top 10
const topPatterns = confusionPatterns.slice(0, 10);

console.log('═══════════════════════════════════════');
console.log('📊 Training Analysis - Last 7 Days');
console.log('═══════════════════════════════════════');
console.log(`Total commands: ${totalCommands}`);
console.log(`Low confidence (<0.7): ${lowConfidenceCount}`);
console.log(`Incorrect feedback: ${incorrectCount}`);
console.log(`Correct feedback: ${correctCount}`);
console.log(`Avg confidence: ${(avgConfidence * 100).toFixed(1)}%`);
console.log(`Accuracy rate: ${accuracyRate.toFixed(1)}%`);
console.log(`Confusion patterns found: ${topPatterns.length}`);
console.log('═══════════════════════════════════════');

return [{
  json: {
    total_commands: totalCommands,
    low_confidence_count: lowConfidenceCount,
    incorrect_action_count: incorrectCount,
    correct_action_count: correctCount,
    avg_confidence: parseFloat(avgConfidence.toFixed(3)),
    accuracy_rate: parseFloat(accuracyRate.toFixed(2)),
    confusion_patterns: topPatterns,
    analysis_date: new Date().toISOString().split('T')[0],
    analysis_period: `${new Date(Date.now() - 7*24*60*60*1000).toISOString().split('T')[0]} to ${new Date().toISOString().split('T')[0]}`
  }
}];

